import sys

def find_initial_cards(n, d, l):
    if n == 2:
        if 1 <= d + 1 <= l and 1 <= 1 <= l:
            return [d + 1, 1]
        elif 1 <= 1 <= l and 1 <= d + 1 <= l:
            return [1, d + 1]
        else:
            return -1
    else:
        result = find_initial_cards(n - 1, d, l)
        if result == -1:
            return -1
        for x in range(1, l + 1):
            if result[-1] - x == d:
                return result + [x]
        return -1

n, d, l = map(int, sys.stdin.read().strip().split())
result = find_initial_cards(n, d, l)
if result == -1:
    print(-1)
else:
    print(' '.join(map(str, result)))
